"use client"

import * as React from "react"
import { motion, useReducedMotion } from "motion/react"
import { Button } from "@/components/ui/button"
import { Checkbox } from "@/components/ui/checkbox"
import { cn } from "@/lib/utils"
import { useControllableState } from "@/hooks/use-controllable-state"
import {
  GridContainer,
  GridSection,
  GridSeparator,
} from "@/components/ui/grid-layout/grid-layout"
import { PhoneInput, maskPhone } from "@/components/ui/phone-input/phone-input"
import { DEFAULT_LABELS, formatLabel } from "./config"
import { Auth03CodeInput } from "./form-parts"
import { createPhoneSchema } from "./schemas"
import type { Auth03Props, Auth03Step } from "./types"
import { useAsyncAction } from "./use-auth-form"

/** 短信为唯一主任务的两步登录界面；真实认证由回调接入。 */
function Auth03({
  onSendCode,
  onVerify,
  onSuccess,
  onAlternative,
  codeLength = 6,
  resendSeconds = 60,
  requireAgreement = true,
  agreementLinks,
  brand,
  labels: labelsProp,
  step: stepProp,
  defaultStep = "phone",
  onStepChange,
  className,
  ...props
}: Auth03Props) {
  const labels = { ...DEFAULT_LABELS, ...labelsProp }
  const [step, setStep] = useControllableState<Auth03Step>({
    prop: stepProp,
    defaultProp: defaultStep,
    onChange: onStepChange,
  })
  const [phone, setPhone] = React.useState("")
  const [sentPhone, setSentPhone] = React.useState("")
  const [code, setCode] = React.useState("")
  const [agreed, setAgreed] = React.useState(false)
  const [agreementError, setAgreementError] = React.useState(false)
  const [phoneError, setPhoneError] = React.useState("")
  const [success, setSuccess] = React.useState(false)
  const [deadline, setDeadline] = React.useState(0)
  const [remaining, setRemaining] = React.useState(0)
  const sending = useAsyncAction(labels.failed)
  const verifying = useAsyncAction(labels.failed)
  const agreementRef = React.useRef<HTMLButtonElement>(null)
  const titleRef = React.useRef<HTMLHeadingElement>(null)
  const previous = React.useRef({ step, success })
  const reduced = useReducedMotion()
  const id = React.useId()
  const length = Math.max(1, Math.min(12, Math.floor(codeLength) || 6))
  const pending = sending.pending || verifying.pending
  React.useEffect(() => {
    if (previous.current.step !== step || previous.current.success !== success)
      titleRef.current?.focus()
    previous.current = { step, success }
  }, [step, success])
  React.useEffect(() => {
    if (!deadline) return
    const tick = () =>
      setRemaining(Math.max(0, Math.ceil((deadline - Date.now()) / 1000)))
    tick()
    const timer = window.setInterval(tick, 250)
    return () => window.clearInterval(timer)
  }, [deadline])
  async function send() {
    if (pending) return
    if (step === "phone") {
      if (requireAgreement && !agreed) {
        setAgreementError(true)
        agreementRef.current?.focus()
        return
      }
      const result = createPhoneSchema(labels).safeParse(phone)
      if (!result.success) {
        setPhoneError(result.error.issues[0]?.message ?? labels.phoneError)
        return
      }
    }
    const target = step === "code" ? sentPhone || phone : phone
    if (!createPhoneSchema(labels).safeParse(target).success) {
      setStep("phone")
      setPhoneError(labels.phoneError)
      return
    }
    if (remaining > 0 && target === sentPhone) return
    if (await sending.run(() => onSendCode(target))) {
      setSentPhone(target)
      setCode("")
      verifying.setError("")
      const seconds = Math.max(0, resendSeconds)
      setRemaining(seconds)
      // 仅在发送成功的事件回调中读取时间，不参与服务端渲染。
      // eslint-disable-next-line react-hooks/purity
      setDeadline(Date.now() + seconds * 1000)
      setStep("code")
    }
  }
  async function verify(value: string) {
    if (pending || success || value.length !== length) return
    if (!sentPhone) {
      setStep("phone")
      return
    }
    if (
      await verifying.run(() => onVerify({ phone: sentPhone, code: value }))
    ) {
      setSuccess(true)
      onSuccess?.()
    }
  }
  return (
    <div
      data-slot="auth-03"
      data-step={step}
      data-state={success ? "success" : "idle"}
      className={cn(
        "w-full overflow-x-clip bg-background text-foreground",
        className,
      )}
      {...props}
    >
      <GridContainer className="max-w-md">
        <GridSection className="px-4 py-8 sm:px-6">
          {brand && (
            <div className="mb-8 flex items-center gap-2 text-sm font-medium">
              {brand.logo}
              {brand.name}
            </div>
          )}
          <h1 className="text-2xl font-semibold tracking-tight">
            {labels.title}
          </h1>
          <p className="mt-2 text-sm leading-7 text-muted-foreground">
            {labels.description}
          </p>
        </GridSection>
        <GridSection
          className="grid grid-cols-2 gap-3 px-4 py-3 text-xs sm:px-6"
          aria-label={labels.steps}
        >
          {["phone", "code"].map((item) => (
            <span
              key={item}
              aria-current={step === item ? "step" : undefined}
              className={cn(
                "border-b border-edge pb-2",
                step === item
                  ? "border-primary text-foreground"
                  : "text-muted-foreground",
              )}
            >
              <span
                aria-hidden="true"
                className="mr-1.5 font-mono tabular-nums"
              >
                {item === "phone" ? "01" : "02"}
              </span>
              {item === "phone" ? labels.phoneStep : labels.codeStep}
            </span>
          ))}
        </GridSection>
        <GridSection className="px-4 py-8 sm:px-6">
          <motion.div
            key={success ? "success" : step}
            data-slot="auth-03-step"
            initial={false}
            animate={
              reduced ? { opacity: 1, y: 0 } : { opacity: [0.7, 1], y: [4, 0] }
            }
            transition={{ duration: reduced ? 0 : 0.18 }}
          >
            <h2
              ref={titleRef}
              tabIndex={-1}
              className="mb-5 text-lg font-medium outline-none focus-visible:underline"
            >
              {success
                ? labels.success
                : step === "phone"
                  ? labels.phoneTitle
                  : labels.codeTitle}
            </h2>
            {success ? (
              <p role="status" className="text-sm text-muted-foreground">
                {labels.successDescription}
              </p>
            ) : step === "phone" ? (
              <form
                noValidate
                onSubmit={(event) => {
                  event.preventDefault()
                  void send()
                }}
                className="space-y-5"
              >
                <PhoneInput
                  label={labels.phone}
                  value={phone}
                  onValueChange={(value) => {
                    setPhone(value)
                    setPhoneError("")
                    sending.setError("")
                  }}
                  size="lg"
                  error={phoneError || sending.error}
                  disabled={pending}
                  required
                  labels={{
                    invalid: labels.phoneError,
                    required: labels.phoneError,
                  }}
                />
                <div className="space-y-2">
                  <div className="flex items-start gap-3 text-xs leading-6">
                    <Checkbox
                      ref={agreementRef}
                      id={`${id}-agreement`}
                      checked={agreed}
                      onCheckedChange={(value) => {
                        setAgreed(value)
                        setAgreementError(false)
                      }}
                      aria-invalid={agreementError || undefined}
                      aria-describedby={
                        agreementError ? `${id}-agreement-error` : undefined
                      }
                      className="mt-1"
                    />
                    <div>
                      <label htmlFor={`${id}-agreement`}>
                        {labels.agreement}
                      </label>
                      {agreementLinks?.terms ? (
                        <a
                          href={agreementLinks.terms}
                          className="underline underline-offset-4"
                        >
                          {labels.terms}
                        </a>
                      ) : (
                        labels.terms
                      )}
                      {labels.and}
                      {agreementLinks?.privacy ? (
                        <a
                          href={agreementLinks.privacy}
                          className="underline underline-offset-4"
                        >
                          {labels.privacy}
                        </a>
                      ) : (
                        labels.privacy
                      )}
                    </div>
                  </div>
                  {agreementError && (
                    <p
                      role="alert"
                      id={`${id}-agreement-error`}
                      className="text-xs text-destructive"
                    >
                      {labels.agreementError}
                    </p>
                  )}
                </div>
                <Button
                  type="submit"
                  size="lg"
                  className="w-full"
                  disabled={pending || (remaining > 0 && phone === sentPhone)}
                >
                  {sending.pending
                    ? labels.sending
                    : remaining > 0 && phone === sentPhone
                      ? formatLabel(labels.countdown, { seconds: remaining })
                      : labels.send}
                </Button>
              </form>
            ) : (
              <form
                noValidate
                onSubmit={(event) => {
                  event.preventDefault()
                  void verify(code)
                }}
                className="space-y-5"
              >
                {/* 脱敏号码和「修改号码」放在同一行，窄屏放不下时自然换行 */}
                <div className="flex flex-wrap items-baseline gap-x-3 gap-y-1 text-sm">
                  <p className="font-mono text-muted-foreground">
                    {formatLabel(labels.sent, {
                      phone: maskPhone(sentPhone || phone),
                    })}
                  </p>
                  {/* 例外：行内文字链接，高度跟随文字，不占按钮的三档高度 */}
                  <Button
                    type="button"
                    variant="link"
                    size="sm"
                    disabled={pending}
                    className="h-auto px-0 pointer-coarse:h-auto"
                    onClick={() => {
                      setStep("phone")
                      setCode("")
                      verifying.setError("")
                      sending.setError("")
                    }}
                  >
                    {labels.edit}
                  </Button>
                </div>
                <div className="space-y-2">
                  <Auth03CodeInput
                    length={length}
                    value={code}
                    label={formatLabel(labels.code, { length })}
                    disabled={pending}
                    error={!!verifying.error}
                    describedBy={
                      verifying.error ? `${id}-code-error` : undefined
                    }
                    onChange={(value) => {
                      setCode(value)
                      verifying.setError("")
                    }}
                    onComplete={(value) => void verify(value)}
                  />
                  {verifying.error && (
                    <p
                      role="alert"
                      id={`${id}-code-error`}
                      className="text-xs text-destructive"
                    >
                      {verifying.error}
                    </p>
                  )}
                </div>
                <Button
                  size="lg"
                  type="submit"
                  className="w-full"
                  disabled={pending || code.length !== length}
                >
                  {verifying.pending ? labels.verifying : labels.verify}
                </Button>
                <Button
                  size="lg"
                  type="button"
                  variant="link"
                  className="w-full"
                  disabled={pending || remaining > 0}
                  onClick={() => void send()}
                >
                  {sending.pending
                    ? labels.sending
                    : remaining > 0
                      ? formatLabel(labels.countdown, { seconds: remaining })
                      : labels.resend}
                </Button>
                {sending.error && (
                  <div
                    role="alert"
                    className="space-y-2 text-xs text-destructive"
                  >
                    <p>{sending.error}</p>
                    <p>{labels.limit}</p>
                  </div>
                )}
              </form>
            )}
          </motion.div>
        </GridSection>
        <GridSeparator />
        <GridSection className="px-4 py-5 text-center sm:px-6">
          <Button
            type="button"
            variant="link"
            size="lg"
            onClick={() => onAlternative?.("password")}
          >
            {labels.alternative}
          </Button>
        </GridSection>
      </GridContainer>
    </div>
  )
}
export { Auth03 }
export type { Auth03Props, Auth03Step }
export type { Auth03Labels } from "./config"

"use client"

import * as React from "react"

type UseControllableStateParams<T> = {
  /** 受控值；传入后组件不再维护内部状态 */
  prop?: T
  /** 非受控时的初始值 */
  defaultProp: T
  /** 值变化时回调（受控与非受控都会触发） */
  onChange?: (value: T) => void
}

/**
 * 同时支持受控与非受控的状态 hook。
 * 约定见 component-conventions 技能第 4 节：open/defaultOpen/onOpenChange 等成对 props 都用它实现。
 */
function useControllableState<T>({
  prop,
  defaultProp,
  onChange,
}: UseControllableStateParams<T>) {
  const [uncontrolled, setUncontrolled] = React.useState(defaultProp)
  const isControlled = prop !== undefined
  const value = isControlled ? prop : uncontrolled

  // 用 ref 保存最新的回调和值，保证 setValue 引用稳定
  const onChangeRef = React.useRef(onChange)
  const valueRef = React.useRef(value)
  React.useEffect(() => {
    onChangeRef.current = onChange
    valueRef.current = value
  })

  const setValue = React.useCallback(
    (next: React.SetStateAction<T>) => {
      const resolved =
        typeof next === "function"
          ? (next as (prev: T) => T)(valueRef.current)
          : next
      if (Object.is(resolved, valueRef.current)) return
      valueRef.current = resolved
      if (!isControlled) setUncontrolled(resolved)
      onChangeRef.current?.(resolved)
    },
    [isControlled],
  )

  return [value, setValue] as const
}

export { useControllableState }

"use client"
import * as React from "react"
import { Auth03 } from "@/components/auth-03/auth-03"
/** 演示后端仅用于体验界面，接入时替换为真实短信和认证服务。 */
export default function LoginPage() {
  const [notice, setNotice] = React.useState("")
  return (
    <main
      data-slot="auth-03-demo"
      className="flex min-h-screen flex-col justify-center bg-background px-4 py-8 text-foreground"
    >
      <p className="mb-4 text-center text-xs text-muted-foreground">
        演示验证码：123456
      </p>
      <Auth03
        brand={{ name: "云间工作台" }}
        onSendCode={async (phone) => {
          await new Promise((resolve) => setTimeout(resolve, 350))
          if (phone.endsWith("0000")) throw new Error("发送太频繁，请稍后再试")
        }}
        onVerify={async ({ code }) => {
          await new Promise((resolve) => setTimeout(resolve, 350))
          if (code !== "123456") throw new Error("验证码错误，请重新输入")
        }}
        onAlternative={() => setNotice("请在接入后打开账号密码登录页面")}
      />
      <p
        role="status"
        className="mt-4 text-center text-xs text-muted-foreground"
      >
        {notice}
      </p>
    </main>
  )
}

import { z } from "zod"
import type { Auth03Labels } from "./config"
function createPhoneSchema(labels: Auth03Labels) {
  return z.string().regex(/^1[3-9]\d{9}$/, labels.phoneError)
}
export { createPhoneSchema }

import type * as React from "react"
import type { Auth03Labels } from "./config"
type Auth03Step = "phone" | "code"
type Auth03Props = Omit<React.ComponentProps<"div">, "onSuccess"> & {
  /** 发送短信，失败时抛出 Error；号码为不带区号的 11 位数字。 */
  onSendCode: (phone: string) => Promise<void>
  /** 验证短信，失败时抛出 Error。 */
  onVerify: (values: { phone: string; code: string }) => Promise<void>
  /** 验证成功后的通知。 */
  onSuccess?: () => void
  /** 其他登录入口，由接入方处理导航。 */
  onAlternative?: (method: "password") => void
  /** 验证码位数。@default 6 */
  codeLength?: number
  /** 重发间隔秒数。@default 60 */
  resendSeconds?: number
  /** 是否必须同意协议。@default true */
  requireAgreement?: boolean
  /** 协议链接；未提供时仅显示协议名称。 */
  agreementLinks?: { terms?: string; privacy?: string }
  /** 品牌名称和标志。 */
  brand?: { name: string; logo?: React.ReactNode }
  /** 覆盖默认中文文案。 */
  labels?: Partial<Auth03Labels>
  /** 受控步骤。 */
  step?: Auth03Step
  /** 初始步骤。@default "phone" */
  defaultStep?: Auth03Step
  /** 步骤变化通知。 */
  onStepChange?: (step: Auth03Step) => void
}
export type { Auth03Props, Auth03Step }

"use client"
import * as React from "react"
/** 用同步锁拦截自动提交与回车的重复请求。 */
function useAsyncAction(fallback: string) {
  const lock = React.useRef(false)
  const [pending, setPending] = React.useState(false)
  const [error, setError] = React.useState("")
  async function run(action: () => Promise<void>) {
    if (lock.current) return false
    lock.current = true
    setPending(true)
    setError("")
    try {
      await action()
      return true
    } catch (caught) {
      setError(caught instanceof Error ? caught.message : fallback)
      return false
    } finally {
      lock.current = false
      setPending(false)
    }
  }
  return { pending, error, setError, run }
}
export { useAsyncAction }

"use client"
import {
  InputOTP,
  InputOTPGroup,
  InputOTPSlot,
} from "@/components/ui/input-otp"
function Auth03CodeInput({
  length,
  value,
  error,
  describedBy,
  label,
  disabled,
  onChange,
  onComplete,
}: {
  length: number
  value: string
  error: boolean
  describedBy?: string
  label: string
  disabled: boolean
  onChange: (value: string) => void
  onComplete: (value: string) => void
}) {
  return (
    <div data-slot="auth-03-code-input">
      <InputOTP
        maxLength={length}
        value={value}
        onChange={onChange}
        onComplete={onComplete}
        pattern="^[0-9]*$"
        autoComplete="one-time-code"
        inputMode="numeric"
        aria-label={label}
        aria-invalid={error || undefined}
        aria-describedby={describedBy}
        disabled={disabled}
        containerClassName="w-full"
      >
        <InputOTPGroup className="w-full">
          {Array.from({ length }, (_, index) => (
            <InputOTPSlot
              key={index}
              index={index}
              aria-invalid={error || undefined}
              className="h-9 min-w-0 flex-1 border-edge text-base data-[active=true]:border-foreground/25 data-[active=true]:bg-muted/40 data-[active=true]:ring-0 pointer-coarse:h-11"
            />
          ))}
        </InputOTPGroup>
      </InputOTP>
    </div>
  )
}
export { Auth03CodeInput }
